"""Compose honest portfolio boards around current, unaltered UI screenshots."""
from pathlib import Path
import json,base64,html,hashlib,sys
from playwright.sync_api import sync_playwright
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'dist';P=D/'portfolio';P.mkdir(exist_ok=True)
sys.path.insert(0,str(ROOT));from release_tools import runtime_digest
items=[
 ('forest','Forest','Your study day,<br>in one place.','Return to a lecture, finish a draft, and keep your active classes close.','Study desk · Library · Card Studio','Atelier-1.0.2-Forest-Home.png','#081d15','#173e2d','#c5d79a','#f2f4df'),
 ('rose','Rose Quartz','From source<br>to study card.','Write, mask, review—and choose what gets added to Anki.','Sources · Drafts · Approval','Atelier-1.0.2-Rose-Card-Studio.png','#f1e6e8','#e1c6d2','#853c62','#482936'),
 ('glacier','Glacier','Mix lectures.<br>Keep context.','Shuffle whole-folder study using Anki’s saved display order. The lecture label stays with its card.','New in 1.0.2 · Parent-folder shuffle','Atelier-1.0.2-Folder-Shuffle.png','#0d2435','#214b64','#a9e7ef','#ebf7fd'),
 ('tidal','Tidal','Practice for<br>the real thing.','Build a mock or rehearsal from your own cards. Independent practice stays separate from scheduled review.','Practice builder · Existing cards','Atelier-1.0.2-Tidal-Practice.png','#e2f0ed','#afcec7','#296d73','#193d43'),
 ('midnight','Midnight','Make the home<br>work for you.','Arrange built-in widgets and keep useful ones on your Study desk. Onigiri is optional.','Native widgets · Personal layout','Atelier-1.0.2-Midnight-Widgets.png','#091215','#14323a','#79dbd0','#e6f3ee'),
 ('ember','Ember','Keep the card<br>in focus.','Quieter context and familiar answer controls, with Anki’s card renderer underneath.','Reviewer · Optional lecture context','Atelier-1.0.2-Ember-Reviewer.png','#211715','#543727','#edbb87','#fae9d7'),
]
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
def board(item):
 key,name,title,body,detail,img,bg,surface,accent,text=item
 return '''<!doctype html><html><meta charset="utf-8"><style>*{box-sizing:border-box}html,body{margin:0;width:1600px;height:1000px;overflow:hidden}body{color:TEXT;font:18px/1.6 Arial,sans-serif;background:radial-gradient(ellipse at 94% 14%,SURFACE,transparent 66%),BG}.backdrop{position:absolute;inset:0;opacity:.10;background:repeating-linear-gradient(126deg,transparent 0,transparent 220px,ACCENT 221px,transparent 222px)}header{position:absolute;left:64px;right:64px;top:42px;display:flex;justify-content:space-between;align-items:center;padding-bottom:20px;border-bottom:1px solid color-mix(in srgb,TEXT 24%,transparent)}.brand{font:bold 32px Arial;letter-spacing:-1.2px}.brand span{font:13px Arial;letter-spacing:2.6px;text-transform:uppercase;margin-left:20px;opacity:.75}.world{font-size:14px;border:1px solid color-mix(in srgb,TEXT 32%,transparent);border-radius:30px;padding:8px 17px}.copy{position:absolute;left:64px;top:238px;width:365px}.eyebrow{color:ACCENT;font-size:12px;letter-spacing:2.5px;text-transform:uppercase}.copy h1{font:500 52px/1.1 Georgia,serif;letter-spacing:-1.5px;margin:24px 0}.copy p{font-size:19px;line-height:1.6;max-width:320px;opacity:.88}.detail{margin-top:34px;padding-top:17px;border-top:1px solid color-mix(in srgb,TEXT 24%,transparent);font-size:13px;max-width:325px;line-height:1.7}.screen{margin:0;position:absolute;left:462px;right:58px;top:148px;bottom:86px;display:flex;align-items:center;justify-content:center}.screen img{display:block;width:100%;max-height:100%;object-fit:contain;border-radius:15px;box-shadow:0 34px 70px #00000035;outline:1px solid color-mix(in srgb,TEXT 28%,transparent)}footer{position:absolute;left:64px;right:58px;bottom:35px;display:flex;justify-content:space-between;gap:15px;font-size:12px;opacity:.77}footer strong{font-weight:600;letter-spacing:.6px}</style><body><div class="backdrop"></div><header><div class="brand">atelier<span>For desktop Anki</span></div><div class="world">WORLDNAME</div></header><section class="copy"><div class="eyebrow">Your space to learn</div><h1>TITLE</h1><p>BODY</p><div class="detail">DETAIL</div></section><figure class="screen"><img src="IMAGE" alt="Actual Atelier interface"></figure><footer><strong>ATELIER 1.0.2 · DAEDALUS WORKS</strong><span>Current UI · Fictional sample data · Browser rendering, not a native-platform claim</span></footer></body></html>'''.replace('WORLDNAME',html.escape(name)).replace('TITLE',title).replace('BODY',html.escape(body)).replace('DETAIL',html.escape(detail)).replace('TEXT',text).replace('SURFACE',surface).replace('ACCENT',accent).replace('BG',bg).replace('IMAGE',data(D/img))
rows=[];evidence=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':1600,'height':1000})
 for item in items:
  p.set_content(board(item));p.wait_for_function('[...document.images].every(x=>x.complete&&x.naturalWidth>0)');p.screenshot(path=str(P/(item[0]+'.png')),animations='disabled')
  rows.append({'id':item[0],'name':item[1],'title':item[2].replace('<br>',' '),'poster':data(P/(item[0]+'.png')),'screen':data(D/item[5])})
 b.close()
# Contact sheet from the real poster images, not invented interface variations.
sheet=Image.new('RGB',(1600,1580),'#edeae5');draw=ImageDraw.Draw(sheet)
for i,item in enumerate(items):
 im=Image.open(P/(item[0]+'.png')).convert('RGB');im.thumbnail((780,490));x=15+(i%2)*795;y=24+(i//2)*518;sheet.paste(im,(x,y));draw.text((x,y+490),item[1]+' / Atelier 1.0.2',fill='#302e2c')
sheet.save(D/'Atelier-1.0.2-Theme-Lineup.png')
gallery='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atelier 1.0.2 — Portfolio</title><style>*{box-sizing:border-box}body{margin:0;background:#efeee9;color:#242c29;font:16px/1.6 system-ui}main{max-width:1460px;margin:auto;padding:32px 22px}h1{font:500 clamp(30px,4vw,52px)/1.15 Georgia;margin:12px 0}p{max-width:78ch;color:#59625c}.bar{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0}button{font:inherit;border:1px solid #9fa99e;background:transparent;color:inherit;padding:8px 14px;border-radius:8px;cursor:pointer}button[aria-pressed=true]{background:#193b2c;color:#eff3e9}button:focus-visible{outline:3px solid #5b8060;outline-offset:3px}img{display:block;width:100%;height:auto;border-radius:12px;border:1px solid #c8d0c8}.meta{font-size:13px}footer{margin-top:18px;font-size:13px;color:#58665b}.sample{font-size:12px;letter-spacing:2px;text-transform:uppercase}</style><main><span class="sample">Atelier / 1.0.2 / Portfolio assets</span><h1>Six worlds. One actual product.</h1><p>These boards use screenshots from the packaged code—not generated replacements for the interface. Choose a world to see its matching workflow, then switch to the full screenshot for detail.</p><nav id="worlds" class="bar"></nav><div id="mode" class="bar"><button data-mode="poster" aria-pressed="true">Portfolio board</button><button data-mode="screen" aria-pressed="false">Full screenshot</button></div><p id="caption" class="meta"></p><img id="view" alt=""><footer>Fictional sample data and browser-rendered interfaces. No invented reviews, outcome promises, native-platform certification or real Anki collection. Whole-folder shuffle saves native display-order settings; independent practice is a separate workflow. Nothing has been posted to GitHub or AnkiWeb by this package.</footer></main><script>const rows=ROWS;let index=0,mode='poster';const bar=document.getElementById('worlds');rows.forEach((r,i)=>{const b=document.createElement('button');b.textContent=r.name;b.onclick=()=>{index=i;render()};bar.append(b)});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});function render(){[...bar.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));const r=rows[index];document.getElementById('caption').textContent=r.name+' — '+r.title;const img=document.getElementById('view');img.src=r[mode];img.alt=r.name+' / '+r.title+' / actual browser-rendered sample';}render();</script></html>'''.replace('ROWS',json.dumps(rows).replace('</',r'<\/'))
(D/'Atelier-1.0.2-Portfolio.html').write_text(gallery)
files=[D/item[5] for item in items]+[D/'Atelier-1.0.2-Theme-Lineup.png']+[P/(item[0]+'.png') for item in items]
for path in files:evidence.append({'file':path.relative_to(D).as_posix(),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'dimensions':list(Image.open(path).size)})
(D/'Atelier-1.0.2-Visual-Evidence.json').write_text(json.dumps({'runtime_sha256':runtime_digest(),'captures':evidence,'native_platform':False,'generated_ui':False},indent=2)+'\n')
print('Rendered',len(items),'portfolio boards, raw screenshots and contact sheet')
